#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum BlockRef {
    Heading { line: usize, structural: bool },
    Paragraph { line: usize },
    ListItem { line: usize, item: u32 },
    FormattedParagraph { line: usize, structural: bool },
    FormattedListItem { line: usize, item: u32, structural: bool },
    TableCell { table_line: usize, row: usize, col: usize },
}

impl BlockRef {
    pub fn widget_id(&self, ui: &egui::Ui) -> egui::Id {
        // Mirror StickyFocus / rendered_focus current scheme.
        // Example skeleton:
        match self {
            BlockRef::Heading { line, structural } => ui.id().with("heading").with(*line).with(*structural),
            BlockRef::Paragraph { line } => ui.id().with("para").with(*line),
            BlockRef::ListItem { line, item } => ui.id().with("list").with(*line).with(*item),
            BlockRef::FormattedParagraph { line, structural } => ui.id().with("fpara").with(*line).with(*structural),
            BlockRef::FormattedListItem { line, item, structural } => ui.id().with("flist").with(*line).with(*item).with(*structural),
            BlockRef::TableCell { table_line, row, col } => ui.id().with("cell").with(*table_line).with(*row).with(*col),
        }
    }
}
```

