4. Define RenderedEditSession struct:
```rust
pub struct RenderedEditSession {
    pub active: Option<BlockRef>,
    pub blocks: std::collections::HashMap<BlockRef, BlockEditState>,
}

impl RenderedEditSession {
    pub fn new() -> Self {
        Self { active: None, blocks: HashMap::new() }
    }

    pub fn switch_to(&mut self, ctx: &egui::Context, block: BlockRef, activation: PendingActivation) {
        if self.active == Some(block) {
            // same block; just update pending activation
            let state = self.blocks.entry(block).or_insert_with(|| BlockEditState {
                text: String::new(),
                formatted_editing: false,
                dirty: false,
                pending_activation: None,
            });
            state.pending_activation = Some(activation);
            return;
        }
        self.close_active(CommitPolicy::SaveIfDirty);
        self.active = Some(block);
        let state = self.blocks.entry(block).or_insert_with(|| BlockEditState {
            text: String::new(),
            formatted_editing: false,
            dirty: false,
            pending_activation: None,
        });
        state.pending_activation = Some(activation);
        // Focus will be applied by the TextEdit the next frame.
    }

    pub fn close_active(&mut self, policy: CommitPolicy) {
        if let Some(active_block) = self.active.take() {
            if let Some(state) = self.blocks.get_mut(&active_block) {
                if state.formatted_editing {
                    state.formatted_editing = false;
                }
                if state.dirty {
                    match policy {
                        CommitPolicy::SaveIfDirty => {
                            // actual source write is injected by callers via callback
                        }
                        CommitPolicy::Discard => {
                            // mark as clean; caller reloads from source on next open
                        }
                    }
                    state.dirty = false;
                }
            }
            // surrender egui focus: TextEdit should set .lost_focus() path naturally
        }
    }

    pub fn on_text_changed(&mut self, block: BlockRef, new_text: String) {
        let state = self.blocks.entry(block).or_insert_with(|| BlockEditState {
            text: String::new(),
            formatted_editing: false,
            dirty: false,
            pending_activation: None,
        });
        state.text = new_text;
        state.dirty = true;
    }
}

pub enum CommitPolicy {
    SaveIfDirty,
    Discard,
}
```

