6. Initially, implement only heading and paragraph commit callbacks:
   - Provide methods that allow caller to pass closures for commit, so session remains UI‑agnostic:
```rust
impl RenderedEditSession {
    pub fn commit_active<F>(&mut self, mut commit_fn: F)
    where
        F: FnMut(BlockRef, &BlockEditState),
    {
        if let Some(block) = self.active {
            if let Some(state) = self.blocks.get_mut(&block) {
                if state.dirty {
                    commit_fn(block, state);
                    state.dirty = false;
                }
            }
        }
    }
}
```

