**Primary Targets**: `src/state.rs` (Tab struct, `with_file_bytes`), `src/app/file_ops.rs` (file loading logic).

**Phase 1 Implementation**:

1. **Add Loading State to Tab struct** (`src/state.rs`):
```rust
#[derive(Clone, Debug)]
pub enum TabContent {
    Loading { path: PathBuf, progress: f32, bytes_loaded: usize, total_size: usize },
    Loaded(String),
    Error(String),
}

impl Tab {
    pub fn is_loading(&self) -> bool { matches!(&self.content, TabContent::Loading {..}) }
    pub fn loading_progress(&self) -> Option<f32> { /* extract from Loading */ }
}
```

2. **Replace synchronous load** in `file_ops.rs`/`state.rs`:
```rust
// OLD: tab.content = TabContent::Loaded(std::fs::read_to_string(&path)?);

// NEW: Spawn background thread
let path_clone = path.clone();
let app_tx = app_tx.clone();
std::thread::spawn(move || {
    let mut total_size = 0;
    if let Ok(metadata) = std::fs::metadata(&path_clone) {
        total_size = metadata.len() as usize;
    }

    let mut file = std::fs::File::open(&path_clone).unwrap();
    let mut buffer = Vec::with_capacity(1024 * 1024); // 1MB chunks
    let mut full_content = String::with_capacity(total_size);
    let mut bytes_loaded = 0;

    loop {
        let chunk_size = file.read_to_end(&mut buffer).unwrap_or(0);
        if chunk_size == 0 { break; }

        full_content.push_str(std::str::from_utf8(&buffer[..chunk_size]).unwrap());
        bytes_loaded += chunk_size;

        let progress = (bytes_loaded as f32 / total_size as f32).min(1.0);
        app_tx.send(AppMsg::FileLoadProgress {
            tab_id: tab_id,
            path: path_clone.clone(),
            progress,
            bytes_loaded,
            total_size,
        }).unwrap();

        buffer.clear();
    }

    app_tx.send(AppMsg::FileLoaded {
        tab_id,
        content: full_content,
    }).unwrap();
});
```

